package com.mfg.erp.controller;import com.mfg.common.api.ApiResponse;import com.mfg.erp.dto.ProductionOrderCommand;import com.mfg.erp.entity.ProductionOrder;import com.mfg.erp.repo.ProductionOrderRepository;import com.mfg.erp.service.ProductionOrderService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/erp/production-orders") @RequiredArgsConstructor public class ProductionOrderController{private final ProductionOrderRepository repo;private final ProductionOrderService service;@GetMapping public ApiResponse<Page<ProductionOrder>> page(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.ok(repo.findAll(PageRequest.of(Math.max(0,page-1),Math.min(200,size))));}@PostMapping public ApiResponse<ProductionOrder> create(@Valid @RequestBody ProductionOrderCommand c){return ApiResponse.ok(service.create(c));}@PostMapping("/{id}/release")public ApiResponse<ProductionOrder> release(@PathVariable Long id){return ApiResponse.ok(service.release(id));}}
